const items = $input.all();

for (const item of items) {
  const html = item.json.html || item.json.data;
  let imageUrl = '';

  if (html) {
    // Try multiple methods to find the best image

    // Method 1: Open Graph image (most reliable for articles)
    let match = html.match(/<meta[^>]*property=["']og:image["'][^>]*content=["']([^"']+)["'][^>]*>/i);
    if (match) {
      imageUrl = match[1];
    }

    // Method 2: Twitter card image
    if (!imageUrl) {
      match = html.match(/<meta[^>]*name=["']twitter:image["'][^>]*content=["']([^"']+)["'][^>]*>/i);
      if (match) {
        imageUrl = match[1];
      }
    }

    // Method 3: Featured/hero images (common in blog posts)
    if (!imageUrl) {
      const featuredSelectors = [
        /<img[^>]*class=["'][^"']*featured[^"']*["'][^>]*src=["']([^"']+)["'][^>]*>/i,
        /<img[^>]*class=["'][^"']*hero[^"']*["'][^>]*src=["']([^"']+)["'][^>]*>/i,
        /<img[^>]*class=["'][^"']*post-image[^"']*["'][^>]*src=["']([^"']+)["'][^>]*>/i,
        /<img[^>]*class=["'][^"']*wp-post-image[^"']*["'][^>]*src=["']([^"']+)["'][^>]*>/i
      ];

      for (const regex of featuredSelectors) {
        match = html.match(regex);
        if (match) {
          imageUrl = match[1];
          break;
        }
      }
    }

    // Method 4: First image in article content
    if (!imageUrl) {
      match = html.match(/<(?:article|div[^>]*class=["'][^"']*(?:content|post|article)[^"']*["'])[^>]*>.*?<img[^>]*src=["']([^"']+)["'][^>]*>/is);
      if (match) {
        imageUrl = match[1];
      }
    }

    // Method 5: Any reasonably sized image (width > 300px)
    if (!imageUrl) {
      const imgMatches = html.match(/<img[^>]*src=["']([^"']+)["'][^>]*>/gi);
      if (imgMatches) {
        for (const imgTag of imgMatches) {
          const srcMatch = imgTag.match(/src=["']([^"']+)["']/);
          const widthMatch = imgTag.match(/width=["']?(\d+)/);

          if (srcMatch && (!widthMatch || parseInt(widthMatch[1]) > 300)) {
            imageUrl = srcMatch[1];
            break;
          }
        }
      }
    }

    // Clean up relative URLs
    if (imageUrl && imageUrl.startsWith('//')) {
      imageUrl = 'https:' + imageUrl;
    } else if (imageUrl && imageUrl.startsWith('/')) {
      const linkUrl = item.json.link || '';
      const baseUrl = linkUrl.match(/^https?:\/\/[^\/]+/);
      if (baseUrl) {
        imageUrl = baseUrl[0] + imageUrl;
      }
    }

    // Validate it's actually an image
    if (imageUrl && !imageUrl.match(/\.(jpg|jpeg|png|gif|webp|svg)(\?.*)?$/i)) {
      // Check if it might be a valid image URL without extension
      if (!imageUrl.includes('image') && !imageUrl.includes('photo') && !imageUrl.includes('pic')) {
        imageUrl = '';
      }
    }
  }

  // Add image data to your item
  item.json.imageUrl = imageUrl;
  item.json.hasImage = !!imageUrl;

  // Log for debugging
  if (imageUrl) {
    console.log(`Found image: ${imageUrl}`);
  } else {
    console.log('No image found for article');
  }
}

return items;

const text = $input.first().json.output;

return [{
  json: {
    linkedin_post: text.replace(/\\n/g, '\n'),
    source_image_url: $input.first().json.source_image_url
  }
}];

const items = $input.all();
const best = items.reduce((top, item) => {
  return item.json.ai_score > top.json.ai_score ? item : top;
}, items[0]);

return [{ json: {
  ...best.json,
  source_link: best.json.source_link || best.json.link || best.json.url || best.json.guid || ''
}}];

return $input.all().map(item => {
  try {
    let raw = item.json.output || '';

    // Strip backticks and json fencing
    raw = raw.replace(/```json|```/g, '').trim();

    // Find JSON object
    const match = raw.match(/\{[\s\S]*\}/);
    if (!match) throw new Error("No JSON object found");

    // Clean common AI mistakes in JSON values
    const cleaned = match[0]
      .replace(/:\s*"([^"]*)"([^,}\]]*)/g, (m, p1, p2) => `: "${p1.replace(/\n/g, ' ')}"${p2}`)
      .replace(/,\s*}/g, '}')
      .replace(/,\s*]/g, ']');

    const parsed = JSON.parse(cleaned);

    return { json: {
      ...item.json,
      ai_score: Number(parsed.score) || 0,
      ai_reason: parsed.reason || '',
      ai_category: parsed.category || '',
      ai_urgency: parsed.urgency || '',
      ai_audience: parsed.audience || '',
      source_link: parsed.link        // ← from AI output
        || item.json.link             // ← from RSS input
        || item.json.url 
        || item.json.guid 
        || ''
    }};
  } catch (e) {
    return { json: {
      ...item.json,
      ai_score: 0,
      ai_reason: "Parse error: " + e.message,
      ai_category: "unknown",
      ai_urgency: "low",
      ai_audience: "all",
      source_link: item.json.link || item.json.url || item.json.guid || ''
    }};
  }
});

// On the error branch, n8n puts the original input under $input.first().json
// but also check the error message context
const json = $input.first().json;

// The RSS title may be nested in the original item that caused the error
const title = json.title 
  || json.headline
  || json.name
  || '';

const snippet = json.contentSnippet 
  || json.summary 
  || json.description
  || json.content
  || '';

// Log what we actually have for debugging
console.log('Available fields:', Object.keys(json));
console.log('Title found:', title);

const fallbackImageUrl = 'https://withagi.space/og-image.png';

const cleanTitle = title
  .replace(/[^a-zA-Z0-9 ]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .split(' ')
  .slice(0, 8)
  .join(' ');

return [{
  json: {
    ...json,
    title,
    snippet,
    fallbackImageUrl,
    searchQuery: cleanTitle || 'artificial intelligence news'
  }
}];

const results = $input.first().json.images_results || [];
const title = $input.first().json.searchQuery || '';
const snippet = $input.first().json.snippet || '';
const fallbackImageUrl = $input.first().json.fallbackImageUrl || '';

if (!results.length) {
  // No results — pass fallback through
  return [{
    json: {
      title,
      snippet,
      fallbackImageUrl,
      imageOptions: [],
      hasFallback: true
    }
  }];
}

// Take top 10 and extract key fields for AI scoring
const imageOptions = results.slice(0, 10).map((img, i) => ({
  index: i,
  url: img.original || img.thumbnail || '',
  title: img.title || '',
  source: img.source || '',
  width: img.original_width || 0,
  height: img.original_height || 0,
  isLandscape: (img.original_width || 0) > (img.original_height || 0)
})).filter(img => img.url);

return [{
  json: {
    title,
    snippet,
    fallbackImageUrl,
    imageOptions,
    hasFallback: false
  }
}];

const raw = $input.first().json.text || $input.first().json.output || '';

let selected;
try {
  const clean = raw.replace(/```json|```/g, '').trim();
  selected = JSON.parse(clean);
} catch (e) {
  // Parse failed — use fallback
  return [{
    json: {
      source_image_url: $input.first().json.fallbackImageUrl || '',
      image_reason: 'AI parse failed — using fallback',
      image_source: 'fallback'
    }
  }];
}

if (!selected?.url) {
  return [{
    json: {
      source_image_url: $input.first().json.fallbackImageUrl || '',
      image_reason: 'No URL in AI response — using fallback',
      image_source: 'fallback'
    }
  }];
}

return [{
  json: {
    imageUrl: selected.url,
    image_reason: selected.reason || '',
    image_source: 'google_search'
  }
}];

// Fallback path — return the OG image passed in from the parent workflow
const fallbackImageUrl = $input.first().json.fallbackImageUrl || '';

return [{
  json: {
    source_image_url: fallbackImageUrl,
    image_reason: 'No Google results found — using site fallback image',
    image_source: 'fallback'
  }
}];

